package override

import (
	"bytes"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/stretchr/testify/require"
)

func TestValidateManifest(t *testing.T) {
	tests := []struct {
		name        string
		mutate      func(t *testing.T, root string)
		wantErr     string
		wantWarning string
	}{
		{name: "valid manifest"},
		{name: "unsupported schema version", mutate: mutateManifest(func(m *manifest) { m.SchemaVersion = 2 }), wantErr: "schema_version must be 1"},
		{name: "missing product", mutate: mutateManifest(func(m *manifest) { m.Overrides[0].Product = "" }), wantErr: "product is required"},
		{name: "missing path", mutate: mutateManifest(func(m *manifest) { m.Overrides[0].Path = "" }), wantErr: "path is required"},
		{name: "missing reason", mutate: mutateManifest(func(m *manifest) { m.Overrides[0].Reason = "" }), wantErr: "reason is required"},
		{name: "missing owner", mutate: mutateManifest(func(m *manifest) { m.Overrides[0].Owner = "" }), wantErr: "owner is required"},
		{name: "missing source URL", mutate: mutateManifest(func(m *manifest) { m.Overrides[0].SourceURL = "" }), wantErr: "source_url is required"},
		{name: "missing reviewed date", mutate: mutateManifest(func(m *manifest) { m.Overrides[0].ReviewedOn = "" }), wantErr: "reviewed_on is required"},
		{name: "missing review due date", mutate: mutateManifest(func(m *manifest) { m.Overrides[0].ReviewDueOn = "" }), wantErr: "review_due_on is required"},
		{name: "duplicate product", mutate: mutateManifest(func(m *manifest) { m.Overrides = append(m.Overrides, m.Overrides[0]) }), wantErr: "duplicate product"},
		{name: "duplicate path", mutate: mutateManifest(func(m *manifest) { m.Overrides[1].Path = m.Overrides[0].Path }), wantErr: "duplicate path"},
		{name: "product does not match API filename", mutate: mutateManifest(func(m *manifest) { m.Overrides[0].Product = "different-product" }), wantErr: "must match product"},
		{name: "missing API file entry", mutate: func(t *testing.T, root string) {
			require.NoError(t, os.WriteFile(filepath.Join(root, "api", "unlisted.json"), []byte("[]"), 0o600))
		}, wantErr: "has no manifest entry"},
		{name: "entry references missing file", mutate: func(t *testing.T, root string) {
			require.NoError(t, os.Remove(filepath.Join(root, "api", "amazon-aurora-mysql.json")))
		}, wantErr: "does not exist"},
		{name: "invalid source URL", mutate: mutateManifest(func(m *manifest) { m.Overrides[0].SourceURL = "http://example.com/source" }), wantErr: "must use https"},
		{name: "malformed source URL", mutate: mutateManifest(func(m *manifest) { m.Overrides[0].SourceURL = "https://[invalid" }), wantErr: "valid https URL"},
		{name: "invalid review date", mutate: mutateManifest(func(m *manifest) { m.Overrides[0].ReviewedOn = "August 5" }), wantErr: "YYYY-MM-DD"},
		{name: "review due before reviewed", mutate: mutateManifest(func(m *manifest) { m.Overrides[0].ReviewDueOn = "2026-08-04" }), wantErr: "before reviewed_on"},
		{name: "review interval over 30 days", mutate: mutateManifest(func(m *manifest) { m.Overrides[0].ReviewDueOn = "2026-09-05" }), wantErr: "exceeds 30 days"},
		{name: "path escapes API directory", mutate: mutateManifest(func(m *manifest) { m.Overrides[0].Path = "api/../manifest.json" }), wantErr: "direct api/"},
		{name: "nested API path", mutate: func(t *testing.T, root string) {
			nested := filepath.Join(root, "api", "nested", "amazon-aurora-mysql.json")
			require.NoError(t, os.MkdirAll(filepath.Dir(nested), 0o700))
			require.NoError(t, os.Rename(filepath.Join(root, "api", "amazon-aurora-mysql.json"), nested))
			mutateManifest(func(m *manifest) { m.Overrides[0].Path = "api/nested/amazon-aurora-mysql.json" })(t, root)
		}, wantErr: "direct api/"},
		{name: "non-JSON API path", mutate: func(t *testing.T, root string) {
			nonJSON := filepath.Join(root, "api", "amazon-aurora-mysql.txt")
			require.NoError(t, os.Rename(filepath.Join(root, "api", "amazon-aurora-mysql.json"), nonJSON))
			mutateManifest(func(m *manifest) { m.Overrides[0].Path = "api/amazon-aurora-mysql.txt" })(t, root)
		}, wantErr: "direct api/"},
		{name: "symlink API path", mutate: func(t *testing.T, root string) {
			target := filepath.Join(t.TempDir(), "outside.json")
			data, err := os.ReadFile(filepath.Join(root, "api", "amazon-aurora-mysql.json"))
			require.NoError(t, err)
			require.NoError(t, os.WriteFile(target, data, 0o600))
			link := filepath.Join(root, "api", "amazon-aurora-mysql.json")
			require.NoError(t, os.Remove(link))
			if err := os.Symlink(target, link); err != nil {
				t.Skipf("platform cannot create symlinks: %v", err)
			}
		}, wantErr: "must not be a symlink"},
		{name: "symlink API directory", mutate: func(t *testing.T, root string) {
			externalAPI := filepath.Join(t.TempDir(), "api")
			require.NoError(t, os.Rename(filepath.Join(root, "api"), externalAPI))
			if err := os.Symlink(externalAPI, filepath.Join(root, "api")); err != nil {
				t.Skipf("platform cannot create symlinks: %v", err)
			}
		}, wantErr: "API directory must not be a symlink"},
		{name: "trailing manifest JSON", mutate: func(t *testing.T, root string) {
			path := filepath.Join(root, "manifest.json")
			file, err := os.OpenFile(path, os.O_APPEND|os.O_WRONLY, 0)
			require.NoError(t, err)
			_, err = file.WriteString("\n{}")
			require.NoError(t, err)
			require.NoError(t, file.Close())
		}, wantErr: "multiple JSON values"},
		{name: "invalid lifecycle data", mutate: func(t *testing.T, root string) {
			require.NoError(t, os.WriteFile(filepath.Join(root, "api", "amazon-aurora-mysql.json"), []byte(`[{"cycle":"3","eol":42}]`), 0o600))
		}, wantErr: "unsupported value type"},
		{name: "malformed optional release date", mutate: func(t *testing.T, root string) {
			require.NoError(t, os.WriteFile(filepath.Join(root, "api", "amazon-aurora-mysql.json"), []byte(`[{"cycle":"3","releaseDate":"2026-1-01"}]`), 0o600))
		}, wantErr: "releaseDate"},
		{name: "malformed optional latest release date", mutate: func(t *testing.T, root string) {
			require.NoError(t, os.WriteFile(filepath.Join(root, "api", "amazon-aurora-mysql.json"), []byte(`[{"cycle":"3","latestReleaseDate":"not-a-date"}]`), 0o600))
		}, wantErr: "latestReleaseDate"},
		{name: "API data is not an array", mutate: func(t *testing.T, root string) {
			require.NoError(t, os.WriteFile(filepath.Join(root, "api", "amazon-aurora-mysql.json"), []byte(`null`), 0o600))
		}, wantErr: "top-level array"},
		{name: "API data has trailing JSON value", mutate: func(t *testing.T, root string) {
			path := filepath.Join(root, "api", "amazon-aurora-mysql.json")
			data, err := os.ReadFile(path)
			require.NoError(t, err)
			data = append(data, []byte("\n{}")...)
			require.NoError(t, os.WriteFile(path, data, 0o600))
		}, wantErr: "multiple JSON values"},
		{name: "overdue review warns", mutate: mutateManifest(func(m *manifest) { m.Overrides[0].ReviewDueOn = "2026-08-06" }), wantWarning: "review overdue"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			root := copyRepositoryFixture(t)
			if tt.mutate != nil {
				tt.mutate(t, root)
			}
			var warnings bytes.Buffer
			err := validateManifest(root, time.Date(2026, 8, 7, 0, 0, 0, 0, time.UTC), &warnings)
			if tt.wantErr != "" {
				require.ErrorContains(t, err, tt.wantErr)
				return
			}
			require.NoError(t, err)
			require.Contains(t, warnings.String(), tt.wantWarning)
		})
	}
}

func TestValidateManifestReviewDueDateBoundary(t *testing.T) {
	tests := []struct {
		name        string
		now         time.Time
		wantWarning string
	}{
		{name: "due date remains valid for full UTC day", now: time.Date(2026, 9, 4, 23, 59, 59, 0, time.UTC)},
		{name: "following UTC day warns", now: time.Date(2026, 9, 5, 0, 0, 0, 0, time.UTC), wantWarning: "review overdue"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var warnings bytes.Buffer
			require.NoError(t, validateManifest(copyRepositoryFixture(t), tt.now, &warnings))
			require.Equal(t, tt.wantWarning != "", strings.Contains(warnings.String(), "review overdue"))
		})
	}
}

func TestRepositoryManifest(t *testing.T) {
	var warnings bytes.Buffer
	require.NoError(t, validateManifest(".", time.Now().UTC(), &warnings))
	if warnings.Len() > 0 {
		t.Log(strings.TrimSpace(warnings.String()))
	}
}

func mutateManifest(mutate func(*manifest)) func(*testing.T, string) {
	return func(t *testing.T, root string) {
		path := filepath.Join(root, "manifest.json")
		data, err := os.ReadFile(path)
		require.NoError(t, err)
		var m manifest
		require.NoError(t, json.Unmarshal(data, &m))
		mutate(&m)
		data, err = json.Marshal(m)
		require.NoError(t, err)
		require.NoError(t, os.WriteFile(path, data, 0o600))
	}
}

func copyRepositoryFixture(t *testing.T) string {
	t.Helper()
	root := t.TempDir()
	for _, path := range []string{"manifest.json", "api/amazon-aurora-mysql.json", "api/amazon-opensearch.json"} {
		data, err := os.ReadFile(path)
		require.NoError(t, err)
		destination := filepath.Join(root, path)
		require.NoError(t, os.MkdirAll(filepath.Dir(destination), 0o700))
		require.NoError(t, os.WriteFile(destination, data, 0o600))
	}
	return root
}

package override

import (
	"encoding/json"
	"fmt"
	"io"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/block/Version-Guard/pkg/eol/endoflife"
)

const (
	manifestSchemaVersion = 1
	dateLayout            = "2006-01-02"
	maximumReviewInterval = 30 * 24 * time.Hour
)

type manifest struct {
	Overrides     []manifestOverride `json:"overrides"`
	SchemaVersion int                `json:"schema_version"`
}

type manifestOverride struct {
	Product     string `json:"product"`
	Path        string `json:"path"`
	Reason      string `json:"reason"`
	Owner       string `json:"owner"`
	SourceURL   string `json:"source_url"`
	ReviewedOn  string `json:"reviewed_on"`
	ReviewDueOn string `json:"review_due_on"`
}

func validateManifest(root string, now time.Time, warnings io.Writer) error {
	m, err := readManifest(filepath.Join(root, "manifest.json"))
	if err != nil {
		return err
	}
	if m.SchemaVersion != manifestSchemaVersion {
		return fmt.Errorf("schema_version must be %d", manifestSchemaVersion)
	}
	if warnings == nil {
		warnings = io.Discard
	}

	apiDirectory := filepath.Join(root, "api")
	apiInfo, err := os.Lstat(apiDirectory)
	if err != nil {
		return fmt.Errorf("stat API directory: %w", err)
	}
	if apiInfo.Mode()&os.ModeSymlink != 0 {
		return fmt.Errorf("API directory must not be a symlink")
	}
	if !apiInfo.IsDir() {
		return fmt.Errorf("API directory is not a directory")
	}

	products := make(map[string]struct{}, len(m.Overrides))
	paths := make(map[string]struct{}, len(m.Overrides))
	for index := range m.Overrides {
		override := &m.Overrides[index]
		if validationErr := validateOverride(root, override, now.UTC(), warnings, products, paths); validationErr != nil {
			return fmt.Errorf("override %d: %w", index, validationErr)
		}
	}

	apiFiles, err := filepath.Glob(filepath.Join(apiDirectory, "*.json"))
	if err != nil {
		return fmt.Errorf("list API files: %w", err)
	}
	for _, apiFile := range apiFiles {
		relative, err := filepath.Rel(root, apiFile)
		if err != nil {
			return fmt.Errorf("resolve API file %q: %w", apiFile, err)
		}
		relative = filepath.ToSlash(relative)
		if _, ok := paths[relative]; !ok {
			return fmt.Errorf("API file %q has no manifest entry", relative)
		}
	}
	return nil
}

func readManifest(path string) (*manifest, error) {
	file, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("open manifest: %w", err)
	}
	defer file.Close()
	decoder := json.NewDecoder(file)
	decoder.DisallowUnknownFields()
	var m manifest
	if err := decoder.Decode(&m); err != nil {
		return nil, fmt.Errorf("decode manifest: %w", err)
	}
	if err := ensureJSONEOF(decoder); err != nil {
		return nil, fmt.Errorf("decode manifest: %w", err)
	}
	return &m, nil
}

//nolint:gocyclo // Validation intentionally reports the first field-specific policy violation.
func validateOverride(root string, override *manifestOverride, now time.Time, warnings io.Writer, products, paths map[string]struct{}) error {
	required := []struct {
		name  string
		value string
	}{
		{"product", override.Product}, {"path", override.Path}, {"reason", override.Reason},
		{"owner", override.Owner}, {"source_url", override.SourceURL},
		{"reviewed_on", override.ReviewedOn}, {"review_due_on", override.ReviewDueOn},
	}
	for _, field := range required {
		if strings.TrimSpace(field.value) == "" {
			return fmt.Errorf("%s is required", field.name)
		}
	}
	if _, exists := products[override.Product]; exists {
		return fmt.Errorf("duplicate product %q", override.Product)
	}
	products[override.Product] = struct{}{}
	if _, exists := paths[override.Path]; exists {
		return fmt.Errorf("duplicate path %q", override.Path)
	}
	paths[override.Path] = struct{}{}

	if !strings.HasPrefix(override.SourceURL, "https://") {
		return fmt.Errorf("source_url must use https")
	}
	if _, err := parseHTTPSURL(override.SourceURL); err != nil {
		return err
	}
	reviewedOn, err := parseManifestDate("reviewed_on", override.ReviewedOn)
	if err != nil {
		return err
	}
	reviewDueOn, err := parseManifestDate("review_due_on", override.ReviewDueOn)
	if err != nil {
		return err
	}
	interval := reviewDueOn.Sub(reviewedOn)
	if interval < 0 {
		return fmt.Errorf("review_due_on is before reviewed_on")
	}
	if interval > maximumReviewInterval {
		return fmt.Errorf("review interval exceeds 30 days")
	}
	if !now.Before(reviewDueOn.AddDate(0, 0, 1)) {
		fmt.Fprintf(warnings, "warning: review overdue for %s (due %s)\n", override.Product, override.ReviewDueOn)
	}

	cleanPath := filepath.ToSlash(filepath.Clean(override.Path))
	filename := strings.TrimPrefix(cleanPath, "api/")
	if cleanPath != override.Path || filename == cleanPath || filename == "" ||
		strings.ContainsAny(filename, `/\`) || filepath.Ext(filename) != ".json" {
		return fmt.Errorf("path %q must be a direct api/<filename>.json path", override.Path)
	}
	if strings.TrimSuffix(filename, ".json") != override.Product {
		return fmt.Errorf("path filename must match product %q", override.Product)
	}
	fullPath := filepath.Join(root, filepath.FromSlash(cleanPath))
	info, err := os.Lstat(fullPath)
	if err != nil {
		if os.IsNotExist(err) {
			return fmt.Errorf("path %q does not exist", override.Path)
		}
		return fmt.Errorf("stat path %q: %w", override.Path, err)
	}
	if info.Mode()&os.ModeSymlink != 0 {
		return fmt.Errorf("path %q must not be a symlink", override.Path)
	}
	if !info.Mode().IsRegular() {
		return fmt.Errorf("path %q is not a regular file", override.Path)
	}
	return validateAPIFile(fullPath)
}

func parseHTTPSURL(raw string) (*url.URL, error) {
	parsed, err := url.ParseRequestURI(raw)
	if err != nil || parsed.Scheme != "https" || parsed.Host == "" {
		return nil, fmt.Errorf("source_url must be a valid https URL")
	}
	return parsed, nil
}

func parseManifestDate(name, value string) (time.Time, error) {
	parsed, err := time.Parse(dateLayout, value)
	if err != nil || parsed.Format(dateLayout) != value {
		return time.Time{}, fmt.Errorf("%s must use YYYY-MM-DD", name)
	}
	return parsed, nil
}

func validateAPIFile(path string) error {
	file, err := os.Open(path)
	if err != nil {
		return fmt.Errorf("open API file %q: %w", path, err)
	}
	defer file.Close()
	decoder := json.NewDecoder(file)
	decoder.DisallowUnknownFields()
	var cycles []*endoflife.ProductCycle
	if err := decoder.Decode(&cycles); err != nil {
		return fmt.Errorf("decode API file %q: %w", path, err)
	}
	if cycles == nil {
		return fmt.Errorf("API file %q must contain a top-level array", path)
	}
	if err := ensureJSONEOF(decoder); err != nil {
		return fmt.Errorf("decode API file %q: %w", path, err)
	}
	for index, cycle := range cycles {
		if err := endoflife.ValidateProductCycle(cycle); err != nil {
			return fmt.Errorf("API file %q cycle %d: %w", path, index, err)
		}
	}
	return nil
}

func ensureJSONEOF(decoder *json.Decoder) error {
	var extra any
	if err := decoder.Decode(&extra); err != io.EOF {
		if err == nil {
			return fmt.Errorf("multiple JSON values")
		}
		return err
	}
	return nil
}

