apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "version-guard.fullname" . }}
  namespace: {{ .Release.Namespace }}
  labels:
    {{- include "version-guard.labels" . | nindent 4 }}
spec:
  replicas: {{ .Values.replicaCount }}
  selector:
    matchLabels:
      {{- include "version-guard.selectorLabels" . | nindent 6 }}
  template:
    metadata:
      labels:
        {{- include "version-guard.selectorLabels" . | nindent 8 }}
      {{- with .Values.podAnnotations }}
      annotations:
        {{- toYaml . | nindent 8 }}
      {{- end }}
    spec:
      serviceAccountName: {{ include "version-guard.serviceAccountName" . }}
      securityContext:
        runAsNonRoot: true
        runAsUser: 1000
        seccompProfile:
          type: RuntimeDefault
      containers:
        - name: version-guard
          image: "{{ .Values.image.repository }}:{{ .Values.image.tag | default .Chart.AppVersion }}"
          imagePullPolicy: {{ .Values.image.pullPolicy }}
          securityContext:
            readOnlyRootFilesystem: true
            allowPrivilegeEscalation: false
            capabilities:
              drop:
                - ALL
          ports:
            - name: http-admin
              containerPort: {{ .Values.adminPort }}
              protocol: TCP
            {{- if .Values.temporalMetrics.enabled }}
            - name: http-metrics
              containerPort: {{ .Values.temporalMetrics.port }}
              protocol: TCP
            {{- end }}
          env:
            - name: HTTP_PORT
              value: {{ .Values.adminPort | quote }}
            - name: TEMPORAL_METRICS_ENABLED
              value: {{ .Values.temporalMetrics.enabled | quote }}
            {{- if .Values.temporalMetrics.enabled }}
            - name: TEMPORAL_METRICS_LISTEN_ADDRESS
              value: {{ .Values.temporalMetrics.listenAddress | quote }}
            {{- end }}
            {{- with .Values.env }}
            {{- toYaml . | nindent 12 }}
            {{- end }}
          livenessProbe:
            tcpSocket:
              port: http-admin
            initialDelaySeconds: 10
            periodSeconds: 15
          readinessProbe:
            tcpSocket:
              port: http-admin
            initialDelaySeconds: 5
            periodSeconds: 10
          resources:
            {{- toYaml .Values.resources | nindent 12 }}
          {{- with .Values.volumeMounts }}
          volumeMounts:
            {{- toYaml . | nindent 12 }}
          {{- end }}
      {{- with .Values.extraContainers }}
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.volumes }}
      volumes:
        {{- toYaml . | nindent 8 }}
      {{- end }}

